// Bootstrap: wires renderer + game + HUD + settings + net, owns the frame
// loop, input handling, screen state, and the headless playtest API
// (window.GAME). Solo mode = rounds vs bots; multiplayer = room-code FFA DM.

import { Renderer, MATERIAL_NAMES } from './renderer.js';
import { Game, WEAPONS, characterSpheres, tintForId } from './game.js';
import { MAPS, MAP_LIST } from './maps.js';
import { AudioEngine } from './audio.js';
import { Settings, buildSettingsUI } from './settings.js';
import { HUD, buildBuyMenu, refreshBuyMenu } from './hud.js';
import { Net } from './net.js';

const $ = id => document.getElementById(id);

const settings = new Settings();
const audio = new AudioEngine(settings);
const canvas = $('view');

let renderer;
try {
  renderer = new Renderer(canvas);
} catch (e) {
  $('fatal').textContent = e.message;
  $('fatal').style.display = 'flex';
  throw e;
}

let hud;
let net = null;
let myId = null;
let roomCode = null;
let scores = [];
let screen = 'menu'; // menu | lobby | game | pause | settings | matchend
let buyOpen = false;
let scoreboardOpen = false;
let pointerLocked = false;
let lastT = performance.now();
let fpsAcc = 0, fpsN = 0, fpsShown = 0;
let frameAccum = 0;
let netSendAccum = 0;
let selectedMap = localStorage.getItem('neonstrike.map') || 'vector';
if (!MAPS[selectedMap]) selectedMap = 'vector';

const game = new Game(settings, audio, {
  onPhase(phase) {
    $('phase-banner').textContent = phase === 'buy'
      ? (game.mode === 'dm' ? 'GEAR UP' : `ROUND ${game.round} — BUY PHASE`)
      : 'GO GO GO';
    $('phase-banner').classList.add('show');
    setTimeout(() => $('phase-banner').classList.remove('show'), 1800);
    if (phase === 'buy') { buyOpen = true; syncOverlays(); }
    if (phase === 'live') { buyOpen = false; syncOverlays(); }
  },
  onRoundEnd(won, reason) {
    $('phase-banner').textContent = `${won ? 'ROUND WON' : 'ROUND LOST'} — ${reason}`;
    $('phase-banner').classList.add('show');
    setTimeout(() => $('phase-banner').classList.remove('show'), 2600);
  },
  onMatchEnd(won) {
    $('match-result').textContent = won ? 'VICTORY' : 'DEFEAT';
    $('match-stats').textContent =
      `${game.score.player} : ${game.score.bots} · ${game.kills} kills · ${game.deaths} deaths`;
    showScreen('matchend');
  },
  onKill(bot, head, weapon) {
    hud.addKillfeed(`YOU ${head ? '☠' : '⟶'} ${bot.name} [${WEAPONS[weapon].name}]`, head);
  },
  onDamage() {},
  onPlayerDamage() { hud.onPlayerDamage(); },
  onShot(info) {
    hud.onShot(info, currentCam());
    if (net && game.mode === 'dm') net.sendShoot(game.player.current);
  },
  onRemoteHit(id, dmg, head) {
    if (net) net.sendHit(id, dmg, head);
  },
  onBotShot() {},
});

hud = new HUD(game, settings);

// ---------- camera ----------
let menuYaw = 0;
function currentCam() {
  const basis = game.player ? game.camBasis() : {
    fwd: [Math.sin(menuYaw) * 0.985, -0.17, -Math.cos(menuYaw) * 0.985],
    right: [Math.cos(menuYaw), 0, Math.sin(menuYaw)],
    up: null,
  };
  if (!basis.up) {
    const f = basis.fwd, r = basis.right;
    basis.up = [r[1] * f[2] - r[2] * f[1], r[2] * f[0] - r[0] * f[2], r[0] * f[1] - r[1] * f[0]];
  }
  const gfx = settings.gfx();
  let fov = gfx.fov;
  if (game.player && game.player.scoped) fov *= 0.28;
  return {
    pos: game.player ? game.eyePos() : [Math.sin(menuYaw * 0.3) * 6, 9, 24],
    fwd: basis.fwd,
    right: basis.right,
    up: basis.up,
    fov,
  };
}

// ---------- screens ----------
function showScreen(s) {
  screen = s;
  for (const id of ['menu', 'lobby', 'pause', 'settings-screen', 'matchend']) {
    $(id).style.display = 'none';
  }
  if (s === 'menu') $('menu').style.display = 'flex';
  if (s === 'lobby') $('lobby').style.display = 'flex';
  if (s === 'pause') $('pause').style.display = 'flex';
  if (s === 'settings') $('settings-screen').style.display = 'flex';
  if (s === 'matchend') $('matchend').style.display = 'flex';
  $('hud').style.display = (s === 'game') ? 'block' : 'none';
  $('room-banner').style.display = (roomCode && (s === 'game' || s === 'pause')) ? 'block' : 'none';
  if (s !== 'game') { scoreboardOpen = false; $('scoreboard').style.display = 'none'; }
  syncOverlays();
}

function syncOverlays() {
  $('buy-menu').style.display = (screen === 'game' && buyOpen && game.state !== 'dead') ? 'block' : 'none';
  if (screen === 'game' && buyOpen) refreshBuyMenu($('buy-menu'), game);
  $('respawn-overlay').style.display = (screen === 'game' && game.state === 'dead') ? 'flex' : 'none';
}

let settingsReturnTo = 'menu';
function openSettings(from) {
  settingsReturnTo = from;
  buildSettingsUI($('settings-panel'), settings, () => showScreen(settingsReturnTo));
  showScreen('settings');
}

// ---------- map picker ----------
function buildMapPick() {
  const el = $('map-pick');
  el.innerHTML = '';
  for (const m of MAP_LIST) {
    const card = document.createElement('button');
    card.className = 'map-card' + (m.id === selectedMap ? ' active' : '');
    card.innerHTML = `<span class="map-name">${m.name}</span><span class="map-desc">${m.desc}</span>`;
    card.addEventListener('click', () => {
      selectedMap = m.id;
      localStorage.setItem('neonstrike.map', m.id);
      buildMapPick();
    });
    el.appendChild(card);
  }
}
buildMapPick();

// ---------- game start ----------
function startSolo() {
  audio.unlock();
  audio.startAmbient();
  leaveRoom();
  game.startMatch(MAPS[selectedMap], 'bots');
  renderer.loadMap(MAPS[selectedMap]);
  showScreen('game');
  requestPointerLock();
}

function startDM(mapId) {
  audio.unlock();
  audio.startAmbient();
  game.startMatch(MAPS[mapId] || MAPS.vector, 'dm');
  renderer.loadMap(MAPS[mapId] || MAPS.vector);
  showScreen('game');
  requestPointerLock();
}

function requestPointerLock() {
  if (canvas.requestPointerLock) {
    const r = canvas.requestPointerLock();
    if (r && r.catch) r.catch(() => {});
  }
}

// ---------- multiplayer ----------
function lobbyStatus(msg) { $('lobby-status').textContent = msg; }

function playerName() {
  const v = $('lobby-name').value.trim().toUpperCase().slice(0, 14);
  return v || 'PLAYER';
}

async function ensureNet() {
  if (net) return net;
  net = new Net();
  await net.connect();
  wireNet(net);
  return net;
}

function wireNet(n) {
  n.on('shoot', msg => {
    const r = n.remotePlayers.get(msg.id);
    if (!r || !game.player) return;
    const rel = game.relativeAudio([r.x, r.y + 1.5, r.z]);
    const def = WEAPONS[msg.weapon];
    audio.play(def ? def.sfx : 'shot_rifle', { category: 'sfx', pan: rel.pan, dist: rel.dist, vol: 0.8 });
  });
  n.on('damage', msg => {
    if (msg.id === myId && game.player) {
      const from = n.remotePlayers.get(msg.from);
      game.player.hp = msg.hp;
      hud.onPlayerDamage();
      const src = from ? [from.x, from.y + 1.5, from.z] : game.eyePos();
      const rel = game.relativeAudio(src);
      audio.play('hurt', { category: 'sfx', pan: rel.pan, vol: 0.9 });
    }
  });
  n.on('death', msg => {
    const victim = msg.id === myId ? 'YOU' : (n.remotePlayers.get(msg.id)?.name || '???');
    const killer = msg.by === myId ? 'YOU' : (n.remotePlayers.get(msg.by)?.name || '???');
    hud.addKillfeed(`${killer} ${msg.head ? '☠' : '⟶'} ${victim}`, msg.head);
    if (msg.id === myId) {
      game.dmDied();
      $('respawn-msg').textContent = `taken out by ${killer}`;
      audio.play('round_lose', { category: 'ui', vol: 0.6 });
      syncOverlays();
    } else if (msg.by === myId) {
      game.kills++;
      game.money = Math.min(16000, game.money + 300);
      audio.play('bot_death', { category: 'sfx', vol: 0.7 });
    }
  });
  n.on('respawned', msg => {
    if (msg.id === myId) {
      game.dmRespawned();
      syncOverlays();
      audio.play('round_start', { category: 'ui', vol: 0.6 });
    }
  });
  n.on('scores', msg => { scores = msg.players; renderScoreboard(); });
  n.on('player_join', msg => hud.addKillfeed(`${msg.name} joined`, false));
  n.on('player_leave', msg => hud.addKillfeed(`${msg.name || 'player'} left`, false));
  n.on('match_over', msg => {
    const won = msg.winner.id === myId;
    $('match-result').textContent = won ? 'VICTORY' : `${msg.winner.name} WINS`;
    const me = scores.find(s => s.id === myId);
    $('match-stats').textContent = me ? `${me.kills} kills · ${me.deaths} deaths · room ${roomCode}` : `room ${roomCode}`;
    audio.play(won ? 'round_win' : 'round_lose', { category: 'ui' });
    showScreen('matchend');
  });
  n.on('disconnect', () => {
    if (roomCode) {
      roomCode = null;
      myId = null;
      game.state = 'menu';
      showScreen('menu');
      lobbyStatus('disconnected from server');
    }
  });
}

function leaveRoom() {
  if (net && roomCode) net.leave();
  roomCode = null;
  myId = null;
  scores = [];
  game.remoteTargets = [];
}

function renderScoreboard() {
  const el = $('scoreboard');
  const rows = [...scores].sort((a, b) => b.kills - a.kills || a.deaths - b.deaths);
  el.innerHTML = `<table><tr><th>PLAYER</th><th>K</th><th>D</th></tr>` +
    rows.map(s => `<tr class="${s.id === myId ? 'me' : ''}"><td>${s.name}</td><td>${s.kills}</td><td>${s.deaths}</td></tr>`).join('') +
    `</table>`;
}

$('btn-multi').addEventListener('click', () => { audio.unlock(); showScreen('lobby'); lobbyStatus(''); });
$('btn-lobby-back').addEventListener('click', () => showScreen('menu'));

$('btn-create').addEventListener('click', async () => {
  try {
    lobbyStatus('connecting…');
    await ensureNet();
    const res = await net.createRoom(playerName(), selectedMap);
    roomCode = res.code;
    myId = res.id;
    scores = [{ id: myId, name: playerName(), kills: 0, deaths: 0 }];
    $('room-banner').textContent = `ROOM ${roomCode} — share this code`;
    startDM(selectedMap);
  } catch (e) {
    lobbyStatus(String(e.message || e));
  }
});

$('btn-join').addEventListener('click', async () => {
  const code = $('lobby-code').value.trim().toUpperCase();
  if (code.length !== 4) { lobbyStatus('code is 4 letters'); return; }
  try {
    lobbyStatus('connecting…');
    await ensureNet();
    const res = await net.joinRoom(code, playerName());
    roomCode = res.code;
    myId = res.id;
    scores = res.players || [];
    $('room-banner').textContent = `ROOM ${roomCode}`;
    startDM(res.map);
  } catch (e) {
    lobbyStatus(String(e.message || e));
  }
});

$('btn-respawn').addEventListener('click', () => {
  if (net && game.state === 'dead' && game.respawnT <= 0) net.sendRespawn();
});

// ---------- input ----------
const KEYMAP = { KeyW: 'fwd+', KeyS: 'fwd-', KeyA: 'strafe-', KeyD: 'strafe+' };

document.addEventListener('keydown', e => {
  if (e.repeat) return;
  if (screen === 'game') {
    if (KEYMAP[e.code]) applyMove(e.code, true);
    else if (e.code === 'Space') game.input.jump = true;
    else if (e.code === 'ControlLeft') {
      game.input.crouch = settings.get('controls.crouchToggle') ? !game.input.crouch : true;
    }
    else if (e.code === 'ShiftLeft') game.input.walk = true;
    else if (e.code === 'KeyR') game.reload();
    else if (e.code === 'KeyB') { buyOpen = !buyOpen; syncOverlays(); }
    else if (e.code === 'Tab') { e.preventDefault(); scoreboardOpen = true; updateScoreboardVis(); }
    else if (e.code === 'Digit1') game.switchWeapon(0);
    else if (e.code === 'Digit2') game.switchWeapon(1);
    else if (e.code === 'Digit3') game.switchWeapon(2);
    else if (e.code === 'Escape') { showScreen('pause'); document.exitPointerLock?.(); }
  } else if (screen === 'pause' && e.code === 'Escape') {
    showScreen('game');
    requestPointerLock();
  } else if (screen === 'settings' && e.code === 'Escape') {
    showScreen(settingsReturnTo);
    if (settingsReturnTo === 'game') requestPointerLock();
  } else if (screen === 'matchend' && e.code === 'Escape') {
    leaveRoom();
    game.state = 'menu';
    showScreen('menu');
  } else if (screen === 'lobby' && e.code === 'Escape') {
    showScreen('menu');
  } else if (screen === 'lobby' && e.code === 'Enter') {
    if ($('lobby-code').value.trim().length === 4) $('btn-join').click();
    else $('btn-create').click();
  }
});

document.addEventListener('keyup', e => {
  if (KEYMAP[e.code]) applyMove(e.code, false);
  else if (e.code === 'Space') game.input.jump = false;
  else if (e.code === 'ControlLeft' && !settings.get('controls.crouchToggle')) game.input.crouch = false;
  else if (e.code === 'ShiftLeft') game.input.walk = false;
  else if (e.code === 'Tab') { scoreboardOpen = false; updateScoreboardVis(); }
});

function updateScoreboardVis() {
  $('scoreboard').style.display = (scoreboardOpen && screen === 'game' && game.mode === 'dm') ? 'block' : 'none';
  if (scoreboardOpen) renderScoreboard();
}

function applyMove(code, down) {
  const m = KEYMAP[code];
  const axis = m.slice(0, -1);
  const dir = m.endsWith('+') ? 1 : -1;
  const cur = game.input[axis];
  if (down) game.input[axis] = dir;
  else if (cur === dir) game.input[axis] = 0;
}

canvas.addEventListener('mousedown', e => {
  if (screen !== 'game') return;
  if (!pointerLocked) requestPointerLock();
  if (e.button === 0) game.input.fire = true;
  if (e.button === 2) game.input.scope = !game.input.scope;
});
document.addEventListener('mouseup', e => {
  if (e.button === 0) game.input.fire = false;
});
canvas.addEventListener('contextmenu', e => e.preventDefault());

document.addEventListener('pointerlockchange', () => {
  pointerLocked = document.pointerLockElement === canvas;
  if (!pointerLocked) {
    game.input.fire = false;
    game.input.scope = false;
    if (screen === 'game' && game.state !== 'dead') showScreen('pause');
  }
});

document.addEventListener('mousemove', e => {
  if (!pointerLocked || screen !== 'game' || !game.player) return;
  const sens = settings.get('controls.sensitivity') * 0.0022 *
    (game.player.scoped ? settings.get('controls.adsScale') : 1);
  const inv = settings.get('controls.invertY') ? -1 : 1;
  game.player.yaw += e.movementX * sens;
  game.player.pitch -= e.movementY * sens * inv;
  game.player.pitch = Math.max(-1.55, Math.min(1.55, game.player.pitch));
});

// menu buttons
$('btn-play').addEventListener('click', startSolo);
$('btn-settings').addEventListener('click', () => openSettings('menu'));
$('btn-resume').addEventListener('click', () => { showScreen('game'); requestPointerLock(); });
$('btn-pause-settings').addEventListener('click', () => openSettings('pause'));
$('btn-quit').addEventListener('click', () => { leaveRoom(); game.state = 'menu'; showScreen('menu'); });
$('btn-again').addEventListener('click', () => {
  if (game.mode === 'dm' && roomCode) { showScreen('game'); requestPointerLock(); }
  else startSolo();
});
$('btn-menu').addEventListener('click', () => { leaveRoom(); game.state = 'menu'; showScreen('menu'); });

buildBuyMenu($('buy-menu'), game, item => game.buy(item));

settings.onChange(path => {
  audio.updateAmbient();
  if (path.startsWith('crosshair') || path === '*') hud.updateCrosshair();
});

// ---------- frame loop ----------
function frame(now) {
  const dtRaw = (now - lastT) / 1000;
  lastT = now;
  const dt = Math.min(dtRaw, 0.1);

  const gfx = settings.gfx();
  if (gfx.frameCap > 0) {
    frameAccum += dtRaw;
    if (frameAccum < 1 / gfx.frameCap) {
      requestAnimationFrame(frame);
      return;
    }
    frameAccum = 0;
  } else {
    frameAccum = 0;
  }

  if (screen === 'menu' || screen === 'matchend' || screen === 'lobby') menuYaw += dt * 0.1;
  if (screen === 'game') game.update(dt);

  // multiplayer sync
  if (net && roomCode && game.player && game.mode === 'dm') {
    net.lerpStates(dt);
    const list = net.getRenderList();
    game.remoteTargets = list.filter(r => r.hp > 0);
    netSendAccum += dt;
    if (netSendAccum > 1 / 15) {
      netSendAccum = 0;
      const p = game.player;
      net.sendState({
        x: p.pos[0], y: p.pos[1], z: p.pos[2],
        yaw: p.yaw, pitch: p.pitch, crouch: p.crouching,
        weapon: p.current, hp: p.hp,
      });
    }
  }

  renderer.resize(gfx.resolutionScale);
  const spheres = game.player ? game.renderSpheres() : [];
  if (game.mode === 'dm') {
    for (const r of game.remoteTargets) {
      spheres.push(...characterSpheres([r.x, r.y, r.z], r.yaw, r.crouch, tintForId(r.id)));
    }
  }
  renderer.setSpheres(spheres);
  if (game.player && hud.flashT > 0) {
    const eye = game.eyePos();
    const { fwd } = game.camBasis();
    renderer.setMuzzleLight(eye[0] + fwd[0] * 1.4, eye[1] + fwd[1] * 1.4 - 0.2, eye[2] + fwd[2] * 1.4, 18, [1, 0.75, 0.4]);
  } else {
    renderer.setMuzzleLight(0, -100, 0, 0);
  }
  renderer.render(currentCam(), now / 1000, gfx);

  if (screen === 'game') {
    hud.draw(dt, currentCam());
    hud.updateDOM(dt);
    hud.updateCrosshair();
    if (game.state === 'dead') {
      $('respawn-overlay').style.display = 'flex';
      $('btn-respawn').textContent = game.respawnT > 0 ? `RESPAWN IN ${Math.ceil(game.respawnT)}` : 'RESPAWN';
      $('btn-respawn').disabled = game.respawnT > 0;
    }
  }

  fpsAcc += dtRaw; fpsN++;
  if (fpsAcc >= 0.5) {
    fpsShown = Math.round(fpsN / fpsAcc);
    fpsAcc = 0; fpsN = 0;
    const el = $('fps');
    el.style.display = gfx.showFps ? 'block' : 'none';
    el.textContent = `${fpsShown} FPS · RT ${canvas.width}×${canvas.height}`;
  }

  requestAnimationFrame(frame);
}

// menu background needs a loaded map
renderer.loadMap(MAPS[selectedMap]);
hud.updateCrosshair();
showScreen('menu');
requestAnimationFrame(frame);

// ---------- playtest API ----------
window.GAME = {
  ready: true,
  game, settings, audio, renderer,
  materialNames: MATERIAL_NAMES,
  maps: MAP_LIST.map(m => m.id),
  getNet: () => net,
  test: {
    start(mapId = selectedMap, mode = 'bots') {
      audio.unlock(); audio.startAmbient();
      game.startMatch(MAPS[mapId], mode);
      renderer.loadMap(MAPS[mapId]);
      showScreen('game');
    },
    async startDM(name, opts = {}) {
      $('lobby-name').value = name;
      await ensureNet();
      if (opts.join) {
        const res = await net.joinRoom(opts.join, name);
        roomCode = res.code; myId = res.id; scores = res.players || [];
        startDM(res.map);
      } else {
        const res = await net.createRoom(name, opts.map || selectedMap);
        roomCode = res.code; myId = res.id;
        scores = [{ id: myId, name, kills: 0, deaths: 0 }];
        startDM(opts.map || selectedMap);
      }
      return { code: roomCode, id: myId };
    },
    skipBuy() { if (game.state === 'buy') game.goLive(); },
    state() {
      return {
        screen, gameState: game.state, mode: game.mode, round: game.round, money: game.money,
        kills: game.kills, deaths: game.deaths, score: { ...game.score },
        hp: game.player ? game.player.hp : null,
        pos: game.player ? [...game.player.pos] : null,
        botsAlive: game.bots.filter(b => b.alive).length,
        remoteCount: game.remoteTargets.length,
        roomCode, myId,
        fps: fpsShown,
        canvas: { w: canvas.width, h: canvas.height },
        weapon: game.player ? game.player.current : null,
        ammo: game.player ? game.player.weapons[game.player.current].ammo : null,
      };
    },
    pose(x, y, z, yaw, pitch) {
      game.player.pos = [x, y, z];
      game.player.vel = [0, 0, 0];
      game.player.yaw = yaw;
      game.player.pitch = pitch;
    },
    aimAtBot(i) {
      const b = game.bots[i];
      const eye = game.eyePos();
      const h = b.headPos();
      const d = [h[0] - eye[0], h[1] - eye[1], h[2] - eye[2]];
      game.player.yaw = Math.atan2(d[0], -d[2]);
      game.player.pitch = Math.atan2(d[1], Math.hypot(d[0], d[2]));
    },
    aimAt(x, y, z) {
      const eye = game.eyePos();
      const d = [x - eye[0], y - eye[1], z - eye[2]];
      game.player.yaw = Math.atan2(d[0], -d[2]);
      game.player.pitch = Math.atan2(d[1], Math.hypot(d[0], d[2]));
    },
    fire() { game.tryFire(); },
    damageBot(i, dmg, head = false) { game.damageBot(game.bots[i], dmg, head, 'rifle'); },
    buy(item) { return game.buy(item); },
    setSetting(path, val) { settings.set(path, val); },
    getSetting(path) { return settings.get(path); },
    sfxReport() { return audio.report(); },
    materialView(id) { renderer.debugMat = id; },
    botInfo() {
      return game.bots.map(b => ({
        name: b.name, alive: b.alive, hp: b.hp, state: b.state,
        pos: [+b.pos[0].toFixed(1), +b.pos[1].toFixed(1), +b.pos[2].toFixed(1)],
      }));
    },
    scores: () => scores,
    step(dt) { game.update(dt); },
  },
};
